'use strict';

/**
 * Minimal Annex-B helpers used by the decode pipeline check.
 *
 * The test stream is generated by ffmpeg with `aud=1:repeat-headers=1`, so an
 * access unit starts at every AUD NAL (type 9) and key frames carry their own
 * SPS/PPS. The helpers are intentionally small and stream-agnostic.
 */

function splitNalUnits(buffer) {
  const units = [];
  let start = -1;
  let startLength = 0;
  let index = 0;

  const push = (end) => {
    if (start === -1) return;
    const raw = buffer.subarray(start, end);
    const payload = raw.subarray(startLength);
    if (payload.length === 0) return;
    units.push({ raw, payload, type: payload[0] & 0x1f });
  };

  while (index + 3 < buffer.length) {
    if (buffer[index] === 0 && buffer[index + 1] === 0) {
      if (buffer[index + 2] === 1) {
        push(index);
        start = index;
        startLength = 3;
        index += 3;
        continue;
      }
      if (buffer[index + 2] === 0 && buffer[index + 3] === 1) {
        push(index);
        start = index;
        startLength = 4;
        index += 4;
        continue;
      }
    }
    index += 1;
  }
  push(buffer.length);
  return units;
}

function groupAccessUnits(units) {
  const groups = [];
  let current = [];

  for (const unit of units) {
    const hasSlice = current.some((entry) => entry.type === 1 || entry.type === 5);
    if (unit.type === 9 && current.length > 0) {
      groups.push(current);
      current = [];
    } else if ((unit.type === 7 || unit.type === 8) && hasSlice) {
      groups.push(current);
      current = [];
    }
    current.push(unit);
  }

  if (current.length > 0) groups.push(current);
  return groups;
}

/**
 * SPS + PPS, deduplicated, in stream order. Mirrors the scrcpy config packet,
 * which carries the codec configuration before the first key frame.
 */
function extractConfig(units) {
  const seen = new Set();
  const parts = [];
  for (const unit of units) {
    if (unit.type !== 7 && unit.type !== 8) continue;
    const key = unit.payload.toString('hex');
    if (seen.has(key)) continue;
    seen.add(key);
    parts.push(unit.raw);
  }
  return parts.length > 0 ? Buffer.concat(parts) : null;
}

function toAccessUnits(buffer) {
  const units = splitNalUnits(buffer);
  const groups = groupAccessUnits(units);
  return {
    units,
    config: extractConfig(units),
    frames: groups.map((group) => ({
      data: Buffer.concat(group.map((unit) => unit.raw)),
      key: group.some((unit) => unit.type === 5),
    })),
  };
}

module.exports = { splitNalUnits, groupAccessUnits, extractConfig, toAccessUnits };
